import copy
import logging
from taf.ul.rfsw.ssh.ru import RU
from taf.ul.rfsw.ssh.preferred_user import look_up_preferred_user, is_supported_branch, lookup_latest_branch
from taf.ul.rfsw.ssh.exception import (InvalidRU,
                                       PreferredUserNotKnown,
                                       TXPowerRetrievingNotSupported,
                                       ProcessError)
from taf.ul.rfsw.ssh import features


logger = logging.getLogger(__name__)
logger.addHandler(logging.NullHandler())


class RfswSsh(object):
    def __init__(self):

        self._first_ru = None
        self._release = None

    def prepare_ru(self, ru_name, hops, ru_ssh_service, release=None, fh_interface=None):
        """
        prepare the connection configurations for connecting to RU managed in library in the latter steps.

        :param ru_name: str, capitalized ru name, e.g. AEQC
        :param hops: List[Dict], the VMs/PCs supporting SSH portforwarding in the branch lead to the RU.
        there are several types of hop, 3 of these are same the followings
        1. a hop where an ordinary SSHD service working, e.g.
        {'host': xxx,        # required
        'username': xxx,     # required
        'password': xxx,     # required
        'port': 22,          # optional, 22 by default
        'connecting_timeout': 10,  # optional, 10 by default
        'initialization_commands': []  # optional, [] by default, automatically be executed commands once hop is ready
        }
        2. a hop where an additional SSHD service is needed to support portforwarding
        {'host': xxx,        # required
        'username': xxx,     # required
        'password': xxx,     # required
        'new_port': xxx,     # required, port number for the additional SSHD service
        'port': 22,          # optional, original SSHD service port 22 by default
        'sudo_enabled': True,      # optional, starting the new SSHD on new_port with sudo or not, True by default
        'connecting_timeout': 10,  # optional, 10 by default
        'initialization_commands': []  # optional, [] by default, automatically be executed commands once hop is ready
        }
        3. a hop where a SSHD service is needed in LXC
        {'host': xxx,        # required
        'host_hop': xxx,     # required a hop instance of dict indicates the one mentioned in 1 or 2 example
        'container_id': xxx, # required container id of LXC where the SSHD will be started
        'username': xxx,     # required
        'password': xxx,     # required
        'new_port': xxx,    # required, port number for the additional SSHD service
        'port': 22,          # optional, SSHD service port 22 by default
        'sudo_enabled': False,     # optional, starting the new SSHD on new_port with sudo or not, False by default
        'connecting_timeout': 10,  # optional, 10 by default
        'initialization_commands': []  # optional, [] by default, automatically be executed commands once hop is ready
        }
        :param ru_ssh_service: dict, ru's ssh connection configuration, e.g.
        [{'host': xxx        # required
        'port': 22          # optional, 22 by default
        'connecting_timeout': 10  # optional, 10 by default
        },]
        :param release: str, branch version str, including '22r1', '22r2', '22r3', '22r4', '23r1', '23r1' by default
        :param fh_interface: Optional[str], cpri or ecpri, None by default
        :return: RUs, List[RU]
        :exception: InvalidRU, InvalidBranch, PreferredUserNotKnown
        """
        self._check_ru_name(ru_name)
        release = self._find_release(release)

        prepared_ru_service_config = self._prepare_ru_service_configuration(ru_name,
                                                                            ru_ssh_service,
                                                                            release=release)
        ru = RU.create(hops, prepared_ru_service_config, ru_name, fh_interface)
        ru.setup_connection()
        self._first_ru = ru
        self._release = release
        return ru

    def prepare_next_ru(self, ru_name, ru_ssh_service, fh_interface=None):
        if not self._first_ru:
            raise ProcessError('no ru prepared prior, please call prepare_ue first')

        self._check_ru_name(ru_name)

        prepared_ru_service_config = self._prepare_ru_service_configuration(ru_name,
                                                                            ru_ssh_service,
                                                                            release=self._release)
        ru = self._first_ru.create_next_ru(prepared_ru_service_config, ru_name, fh_interface)
        ru.setup_connection()
        return ru

    def retrieve_tx_power(self, ru, try_sudo=True, username=None):
        """
        retrieve all the tx power information from all the unit (e.g. MADE) of RU

        :param ru: RU, instance of RU, AEQZ and AEHC are supported
        :param try_sudo: bool, try to run command with sudo, if the system cannot support sudo,
        will run command without sudo
        :param username: Optional[str], None by default to use the preferred username
        :return: output from command for retrieving tx power, e.g. 'dapd -sq' for AEHC, AEQZ ...
        """
        supported_rus = features.RetrieveTxPower.retrieve_supported_rus()
        if ru.name not in supported_rus:
            raise TXPowerRetrievingNotSupported("Ru '{}' is unsupported to retrieve tx power, supported RUs are {}".
                                                format(ru.name, supported_rus))

        connection = ru.setup_connection(username=username)
        sudo_enabled = False
        if try_sudo:
            sudo_enabled = self._check_sudo_available(connection)

        return ru.retrieve_tx_power(connection=connection, sudo_enabled=sudo_enabled)

    def release(self):
        """
        disconnect all ru
        :return: None
        """
        if self._first_ru:
            self._first_ru.release()
            self._first_ru = None

    @staticmethod
    def _check_ru_name(ru_name):
        if ru_name not in features.feature_supported_managed_rus:
            raise InvalidRU("ru '{}' is not a managed ru in {}".
                            format(ru_name, features.feature_supported_managed_rus))

    @staticmethod
    def _find_release(release):
        if not release:
            return lookup_latest_branch()

        normalized_version = 'v' + release
        if not is_supported_branch(normalized_version):
            latest_release = lookup_latest_branch()
            logger.warning("branch '{}' is not supported for the RUs managed here, will use latest one '{}'".
                           format(release, latest_release))
            return latest_release

        return normalized_version

    def _prepare_ru_service_configuration(self, ru_name, ru_ssh_service, release):
        preferred_username = self._pick_preferred_username(ru_name=ru_name, release=release)
        new_ru_ssh_service = copy.deepcopy(ru_ssh_service)
        new_ru_ssh_service['username'] = preferred_username
        return new_ru_ssh_service

    @staticmethod
    def _pick_preferred_username(ru_name, release):
        branch_name = release.lower()
        username = look_up_preferred_user(ru_name, branch_name)
        if not username:
            raise PreferredUserNotKnown("ru {} in branch {} has no proper user name provided".
                                        format(ru_name, branch_name))
        return username

    @staticmethod
    def _check_sudo_available(connection):
        output = connection.execute("which sudo")
        logger.debug("check sudo available --> {}".format(output))
        if isinstance(output, bytes):
            return output and b'no sudo' not in output
        return output and 'no sudo' not in output
